use vstd::prelude::*;

// Verus can refer to a Vec<i32> in specs via the “view” `a@` (a sequence),
// and index via `a@.index(i)`.
#[requires(true)]
#[ensures(
    // The result is true exactly when there exists an index i
    // with i + 1 < a@.len() and a@[i] + 1 == a@[i + 1].
    result == (
        exists|i: usize|
            i + 1 < a@.len() &&
            a@.index(i) + 1 == a@.index(i + 1)
    )
)]
fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    // Iterate over all adjacent pairs
    a.windows(2).any(|pair| pair[1] == pair[0] + 1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_and_single() {
        let v: Vec<i32> = vec![];
        assert!(!contains_consecutive_numbers(&v));
        let v = vec![42];
        assert!(!contains_consecutive_numbers(&v));
    }

    #[test]
    fn no_consecutive() {
        let v = vec![1, 3, 2, 5, 5];
        assert!(!contains_consecutive_numbers(&v));
    }

    #[test]
    fn has_consecutive() {
        let v = vec![4, 5];
        assert!(contains_consecutive_numbers(&v));

        let v = vec![0, 1, 1, 2, 3];
        assert!(contains_consecutive_numbers(&v)); // 0->1 and 1->2
    }

    #[test]
    fn negative_values() {
        let v = vec![-3, -2, 0, 1];
        assert!(contains_consecutive_numbers(&v)); // -3->-2 and 0->1
    }
}